function Get-WsmAssistiveOsProvidedCanonicalTaskSecurity($Capture) {
    if($null -eq $Capture -or $Capture.Kind -cne 'TaskSecurityCapture' -or $Capture.SchemaVersion -ne 1 -or -not $Capture.TaskSecuritySddl -or $Capture.Folders -isnot [array]){throw 'Task security capture is missing or malformed.'}
    $taskSddl=ConvertTo-WsmTaskSecuritySddl ([string]$Capture.TaskSecuritySddl)
    if((Get-WsmHashText $taskSddl) -ine [string]$Capture.TaskSecurityHash){throw 'Task security descriptor hash mismatch.'}
    $folderRows=@(foreach($folder in @($Capture.Folders)){
        Assert-WsmFields $folder @('Path','SecuritySddl','SecurityHash') @('Path','SecuritySddl','SecurityHash')
        $path=ConvertTo-WsmTaskSecurityFolderPath ([string]$folder.Path) -AllowRoot
        $sddl=ConvertTo-WsmTaskSecuritySddl ([string]$folder.SecuritySddl)
        if((Get-WsmHashText $sddl) -ine [string]$folder.SecurityHash){throw 'Task folder security descriptor hash mismatch.'}
        [pscustomobject][ordered]@{Path=$path;SecuritySddl=$sddl;SecurityHash=(Get-WsmHashText $sddl)}
    })
    $folders=@($folderRows | Sort-Object Path)
    $expected=@(Get-WsmTaskSecurityFolderAncestors ([string]$Capture.TaskPath) | Sort-Object)
    if(($expected -join '|') -cne (@($folders | ForEach-Object Path) -join '|')){throw 'Task folder security capture is incomplete.'}
    [pscustomobject][ordered]@{TaskSecuritySddl=$taskSddl;TaskSecurityHash=(Get-WsmHashText $taskSddl);Folders=$folders}
}

function Get-WsmAssistiveOsProvidedCaptureDefinition($Capture) {
    Assert-WsmFields $Capture @('SchemaVersion','ToolVersion','Kind','Role','HostFingerprint','HostName','HostOS','HostVersion','HostBuild','HostEdition','HostArchitecture','TaskPath','TaskName','TaskXml','TaskXmlSHA256','TaskSecurityCapture','CapturedUtc','ProductionVerified') @('SchemaVersion','Kind','HostFingerprint','HostName','HostOS','HostVersion','HostBuild','HostEdition','HostArchitecture','TaskPath','TaskName','TaskXml','TaskXmlSHA256','TaskSecurityCapture','CapturedUtc')
    if($Capture.SchemaVersion -ne 1 -or $Capture.Kind -cne 'AssistiveOsProvidedTaskCapture' -or $Capture.HostFingerprint -notmatch '^[a-f0-9]{64}$' -or $Capture.TaskXmlSHA256 -notmatch '^[a-f0-9]{64}$' -or [string]::IsNullOrWhiteSpace([string]$Capture.TaskXml)){throw 'Task definition capture is malformed.'}
    $taskPath=ConvertTo-WsmTaskSecurityFolderPath ([string]$Capture.TaskPath) -AllowRoot
    $taskName=ConvertTo-WsmTaskSecurityTaskName ([string]$Capture.TaskName)
    if([string]$Capture.TaskPath -cne $taskPath -or [string]$Capture.TaskName -cne $taskName -or [string]$Capture.TaskXmlSHA256 -ine (Get-WsmHashText ([string]$Capture.TaskXml))){throw 'Task XML or identity binding is invalid.'}
    $captured=[DateTimeOffset]::MinValue
    if(-not [DateTimeOffset]::TryParse([string]$Capture.CapturedUtc,[ref]$captured) -or $captured.Offset -ne [TimeSpan]::Zero){throw 'Task capture timestamp must be UTC.'}
    if($captured -gt [DateTimeOffset]::UtcNow.AddMinutes(5)){throw 'Task capture timestamp is in the future.'}
    $security=Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $Capture.TaskSecurityCapture
    if([string]$Capture.TaskSecurityCapture.TaskPath -cne $taskPath -or [string]$Capture.TaskSecurityCapture.TaskName -cne $taskName){throw 'Task security capture identity differs from task XML identity.'}
    $securityHash=Get-WsmHashText ($security | ConvertTo-Json -Depth 30 -Compress)
    [pscustomobject][ordered]@{TaskPath=$taskPath;TaskName=$taskName;TaskXmlSHA256=[string]$Capture.TaskXmlSHA256.ToLowerInvariant();TaskSecuritySHA256=$securityHash;HostOS=[string]$Capture.HostOS;HostVersion=[string]$Capture.HostVersion;HostBuild=[string]$Capture.HostBuild;HostEdition=[string]$Capture.HostEdition;HostArchitecture=[string]$Capture.HostArchitecture;CapturedUtc=$captured.ToUniversalTime().ToString('o')}
}

function Export-WsmAssistiveOsProvidedTaskCapture {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$Workspace,[Parameter(Mandatory)][string]$PairId,[Parameter(Mandatory)][int]$DecisionRevision,[Parameter(Mandatory)][string]$TaskPath,[Parameter(Mandatory)][string]$TaskName,[Parameter(Mandatory)][ValidateSet('Source','Target')][string]$Role,[string]$ExpectedHostFingerprint,[string]$OutputPath='')
    Assert-WsmId $PairId
    $taskPath=ConvertTo-WsmTaskSecurityFolderPath $TaskPath -AllowRoot;$taskName=ConvertTo-WsmTaskSecurityTaskName $TaskName
    $identity=Get-WsmMachineIdentity
    if($ExpectedHostFingerprint -and $identity.Fingerprint -ine $ExpectedHostFingerprint){throw ($Role+' capture host differs from the independently expected host fingerprint.')}
    $task=Get-ScheduledTask -TaskName $taskName -TaskPath $taskPath -ErrorAction Stop
    if(@($task).Count -ne 1){throw 'Native Task Scheduler lookup did not return exactly one task.'}
    $xml=[string](Export-ScheduledTask -TaskName $taskName -TaskPath $taskPath -ErrorAction Stop)
    if([string]::IsNullOrWhiteSpace($xml)){throw 'Native Task Scheduler export returned an empty definition.'}
    $security=Capture-WsmTaskSecurity $taskPath $taskName
    $pre=Get-WsmPreflight
    $capture=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='AssistiveOsProvidedTaskCapture';Role=$Role;HostFingerprint=[string]$identity.Fingerprint;HostName=[string]$identity.Name;HostOS=[string]$pre.OS;HostVersion=[string]$pre.Version;HostBuild=[string]$pre.Build;HostEdition=[string]$pre.Edition;HostArchitecture=[string]$pre.Architecture;TaskPath=$taskPath;TaskName=$taskName;TaskXml=$xml;TaskXmlSHA256=(Get-WsmHashText $xml);TaskSecurityCapture=$security;CapturedUtc=(Get-WsmUtc);ProductionVerified=$false}
    [void](Get-WsmAssistiveOsProvidedCaptureDefinition $capture)
    $generated=Get-WsmAssistiveFormDecisionPath $Workspace $PairId $DecisionRevision ('osprovided-'+$Role.ToLowerInvariant()+'-capture')
    $formsRoot=[IO.Path]::GetDirectoryName($generated).TrimEnd('\')+'\';$full=$generated;if($OutputPath){$full=[IO.Path]::GetFullPath($OutputPath)}
    if(-not $full.StartsWith($formsRoot,[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -cne '.json'){throw 'Task capture must be written as a new JSON file in the protected workspace forms directory.'}
    Assert-WsmNoReparse $full;if([IO.File]::Exists($full) -or [IO.Directory]::Exists($full)){throw 'Task capture output exists; choose a new revisioned path.'}
    Write-WsmJson $full $capture
    [pscustomobject][ordered]@{Status='Captured';Role=$Role;Path=[IO.Path]::GetFullPath($full);SHA256=(Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant();HostFingerprint=[string]$identity.Fingerprint;TaskPath=$taskPath;TaskName=$taskName;TaskXmlSHA256=[string]$capture.TaskXmlSHA256;TaskSecuritySHA256=(Get-WsmHashText ((Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $security) | ConvertTo-Json -Depth 30 -Compress));CapturedUtc=[string]$capture.CapturedUtc;RawDefinitionReturned=$false;ReadinessProof=$false;ProductionVerified=$false}
}

function Read-WsmAssistiveOsProvidedCapture([string]$Path,[string]$ExpectedHash) {
    Assert-WsmNoReparse ([IO.Path]::GetFullPath($Path));Assert-WsmTrustedFile $Path $ExpectedHash
    $capture=Read-WsmTrustedJson $Path $ExpectedHash
    [void](Get-WsmAssistiveOsProvidedCaptureDefinition $capture)
    $capture
}

function Export-WsmAssistiveOsProvidedBaseline {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$Workspace,[Parameter(Mandatory)][string]$PairId,[Parameter(Mandatory)][int]$ExpectedDecisionRevision,[Parameter(Mandatory)][string]$SourceCapturePath,[Parameter(Mandatory)][string]$SourceCaptureHash,[Parameter(Mandatory)][string]$TargetCapturePath,[Parameter(Mandatory)][string]$TargetCaptureHash,[Parameter(Mandatory)][string]$SourceProvenancePath,[Parameter(Mandatory)][string]$SourceProvenanceHash,[Parameter(Mandatory)][string]$SourceProvenanceOwner,[Parameter(Mandatory)][string]$TargetProvenancePath,[Parameter(Mandatory)][string]$TargetProvenanceHash,[Parameter(Mandatory)][string]$TargetProvenanceOwner,[Parameter(Mandatory)][string]$ProviderId,[Parameter(Mandatory)][string]$Owner,[Parameter(Mandatory)][switch]$Ack,[Parameter(Mandatory)][switch]$AckPristineBaseline,[string]$OutputPath='')
    if(-not $Ack -or -not $AckPristineBaseline){throw 'Baseline creation requires explicit owner acknowledgment that both supplied captures are independently sourced pristine OS definitions.'}
    Assert-WsmId $PairId;Assert-WsmQualificationText $Owner Owner;Assert-WsmQualificationText $ProviderId ProviderId
    Assert-WsmQualificationText $SourceProvenanceOwner SourceProvenanceOwner;Assert-WsmQualificationText $TargetProvenanceOwner TargetProvenanceOwner
    $catalog=Get-WsmCatalog $Workspace $PairId;if($catalog.DecisionRevision -ne $ExpectedDecisionRevision){throw 'Catalog changed; refresh before exporting the OSProvided baseline.'}
    $source=Read-WsmAssistiveOsProvidedCapture $SourceCapturePath $SourceCaptureHash;$target=Read-WsmAssistiveOsProvidedCapture $TargetCapturePath $TargetCaptureHash
    if([string]$source.Role -cne 'Source' -or [string]$target.Role -cne 'Target' -or [IO.Path]::GetFullPath($SourceCapturePath) -ieq [IO.Path]::GetFullPath($TargetCapturePath)){throw 'Baseline requires separate exact Source and Target native captures.'}
    Assert-WsmNoReparse ([IO.Path]::GetFullPath($SourceProvenancePath));Assert-WsmTrustedFile $SourceProvenancePath $SourceProvenanceHash
    Assert-WsmNoReparse ([IO.Path]::GetFullPath($TargetProvenancePath));Assert-WsmTrustedFile $TargetProvenancePath $TargetProvenanceHash
    $sourceDef=Get-WsmAssistiveOsProvidedCaptureDefinition $source;$targetDef=Get-WsmAssistiveOsProvidedCaptureDefinition $target
    if($sourceDef.TaskPath -cne $targetDef.TaskPath -or $sourceDef.TaskName -cne $targetDef.TaskName){throw 'Source and target baseline captures must identify the exact same task path and name.'}
    $sourceFields=[pscustomobject][ordered]@{OS=$sourceDef.HostOS;Version=$sourceDef.HostVersion;Build=$sourceDef.HostBuild;Edition=$sourceDef.HostEdition;Architecture=$sourceDef.HostArchitecture;TaskPath=$sourceDef.TaskPath;TaskName=$sourceDef.TaskName;TaskXmlSHA256=$sourceDef.TaskXmlSHA256;TaskSecuritySHA256=$sourceDef.TaskSecuritySHA256;ProvenanceReference=[IO.Path]::GetFullPath($SourceProvenancePath);ProvenanceSHA256=$SourceProvenanceHash.ToLowerInvariant();ProvenanceOwner=$SourceProvenanceOwner}
    $targetFields=[pscustomobject][ordered]@{OS=$targetDef.HostOS;Version=$targetDef.HostVersion;Build=$targetDef.HostBuild;Edition=$targetDef.HostEdition;Architecture=$targetDef.HostArchitecture;TaskPath=$targetDef.TaskPath;TaskName=$targetDef.TaskName;TaskXmlSHA256=$targetDef.TaskXmlSHA256;TaskSecuritySHA256=$targetDef.TaskSecuritySHA256;ProvenanceReference=[IO.Path]::GetFullPath($TargetProvenancePath);ProvenanceSHA256=$TargetProvenanceHash.ToLowerInvariant();ProvenanceOwner=$TargetProvenanceOwner}
    $baseline=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='TrustedOsProvidedTaskBaseline';BaselineId=[Guid]::NewGuid().ToString('D');ProviderId=$ProviderId;Source=$sourceFields;Target=$targetFields;SourceCapturePath=[IO.Path]::GetFullPath($SourceCapturePath);SourceCaptureHash=$SourceCaptureHash.ToLowerInvariant();TargetCapturePath=[IO.Path]::GetFullPath($TargetCapturePath);TargetCaptureHash=$TargetCaptureHash.ToLowerInvariant();BaselineOwner=$Owner;PristineAcknowledged=$true;VendorVerified=$false;ReadinessProof=$false;BusinessAcceptance=$false;ExternalProvenanceRetention='External provenance files remain owner-managed and are not automatically cleaned by this workspace.';CreatedUtc=(Get-WsmUtc)}
    $generated=Get-WsmAssistiveFormDecisionPath $Workspace $PairId $ExpectedDecisionRevision 'osprovided-baseline';$formsRoot=[IO.Path]::GetDirectoryName($generated).TrimEnd('\')+'\';$full=$generated;if($OutputPath){$full=[IO.Path]::GetFullPath($OutputPath)}
    if(-not $full.StartsWith($formsRoot,[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -cne '.json'){throw 'Trusted baseline must be written as a new JSON file inside protected workspace forms.'}
    Assert-WsmNoReparse $full;if([IO.File]::Exists($full) -or [IO.Directory]::Exists($full)){throw 'Baseline output exists; choose a new revisioned path.'}
    Write-WsmJson $full $baseline
    [pscustomobject][ordered]@{Status='BaselineRecorded';Path=[IO.Path]::GetFullPath($full);SHA256=(Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant();ProviderId=$ProviderId;Owner=$Owner;SourceOS=($sourceDef.HostOS+' '+$sourceDef.HostVersion+' build '+$sourceDef.HostBuild);TargetOS=($targetDef.HostOS+' '+$targetDef.HostVersion+' build '+$targetDef.HostBuild);TaskPath=$sourceDef.TaskPath;TaskName=$sourceDef.TaskName;VendorVerified=$false;RawDefinitionsReturned=$false;ReadinessProof=$false;BusinessAcceptance=$false}
}

function Get-WsmAssistiveOsProvidedReview {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$Workspace,[Parameter(Mandatory)][string]$PairId,[Parameter(Mandatory)][string]$ItemId,[Parameter(Mandatory)][string]$SourceCapturePath,[Parameter(Mandatory)][string]$SourceCaptureHash,[Parameter(Mandatory)][string]$TargetCapturePath,[Parameter(Mandatory)][string]$TargetCaptureHash,[Parameter(Mandatory)][string]$TargetInventoryPath,[Parameter(Mandatory)][string]$TargetInventoryHash,[Parameter(Mandatory)][string]$BaselinePath,[Parameter(Mandatory)][string]$BaselineHash,[Parameter(Mandatory)][string]$BaselineOwner,[Parameter(Mandatory)][switch]$AckTrustedBaseline)
    if(-not $AckTrustedBaseline){throw 'Owner must explicitly acknowledge the independently supplied trusted baseline hash.'}
    Assert-WsmQualificationText $BaselineOwner BaselineOwner
    $catalog=Get-WsmCatalog $Workspace $PairId
    $sourceCapture=Read-WsmAssistiveOsProvidedCapture $SourceCapturePath $SourceCaptureHash
    $targetCapture=Read-WsmAssistiveOsProvidedCapture $TargetCapturePath $TargetCaptureHash
    Assert-WsmTrustedFile $TargetInventoryPath $TargetInventoryHash;$targetInventory=Read-WsmTrustedJson $TargetInventoryPath $TargetInventoryHash;Assert-WsmInventory $targetInventory
    if($catalog.DecisionRevision -lt 1 -or $catalog.InventoryHash -notmatch '^[a-f0-9]{64}$'){throw 'Current source catalog binding is incomplete.'}
    $items=@($catalog.Items | Where-Object ItemId -CEQ $ItemId)
    if($items.Count -ne 1 -or [string]$items[0].Kind -cne 'ScheduledTask' -or [string]$items[0].Adapter -cne 'ScheduledTask'){throw 'OSProvided review requires one exact source ScheduledTask item.'}
    $item=$items[0];$sourceSettings=$item.Settings
    if(-not $sourceSettings.PSObject.Properties['TaskPath'] -or -not $sourceSettings.PSObject.Properties['TaskName'] -or -not $sourceSettings.PSObject.Properties['Xml']){throw 'Source inventory task definition is incomplete.'}
    $sourceDef=Get-WsmAssistiveOsProvidedCaptureDefinition $sourceCapture;$targetDef=Get-WsmAssistiveOsProvidedCaptureDefinition $targetCapture
    if($sourceCapture.HostFingerprint -ine [string]$catalog.Source.Fingerprint -or $sourceDef.TaskPath -cne [string]$sourceSettings.TaskPath -or $sourceDef.TaskName -cne [string]$sourceSettings.TaskName -or $sourceDef.TaskXmlSHA256 -ine (Get-WsmHashText ([string]$sourceSettings.Xml))){throw 'Source native task capture is not the exact selected source inventory definition.'}
    if(-not $sourceSettings.PSObject.Properties['TaskSecurityCaptureStatus'] -or [string]$sourceSettings.TaskSecurityCaptureStatus -cne 'Captured' -or -not $sourceSettings.PSObject.Properties['TaskSecurityCapture']){throw 'Source inventory has no complete native task security capture.'}
    $sourceInventorySecurity=Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $sourceSettings.TaskSecurityCapture
    if((Get-WsmHashText ($sourceInventorySecurity | ConvertTo-Json -Depth 30 -Compress)) -ine $sourceDef.TaskSecuritySHA256){throw 'Source native security capture differs from the imported source inventory.'}
    if($targetCapture.HostFingerprint -ine [string]$targetInventory.Source.Fingerprint -or $targetDef.TaskPath -cne [string]$sourceSettings.TaskPath -or $targetDef.TaskName -cne [string]$sourceSettings.TaskName){throw 'Target native task capture is not bound to the exact selected task and target inventory host.'}
    $targetItems=@($targetInventory.Items | Where-Object {$_.Category -ceq 'Tasks' -and $_.Kind -ceq 'ScheduledTask' -and $_.Settings.TaskPath -ceq $targetDef.TaskPath -and $_.Settings.TaskName -ceq $targetDef.TaskName})
    if($targetItems.Count -ne 1 -or [string]$targetItems[0].Settings.Xml -cne [string]$targetCapture.TaskXml){throw 'Target inventory is missing the exact current task definition or it differs from native target readback.'}
    $targetSettings=$targetItems[0].Settings
    if(-not $targetSettings.PSObject.Properties['TaskSecurityCaptureStatus'] -or [string]$targetSettings.TaskSecurityCaptureStatus -cne 'Captured' -or -not $targetSettings.PSObject.Properties['TaskSecurityCapture']){throw 'Target inventory has no complete native task security capture.'}
    $targetInventorySecurity=Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $targetSettings.TaskSecurityCapture
    if((Get-WsmHashText ($targetInventorySecurity | ConvertTo-Json -Depth 30 -Compress)) -ine $targetDef.TaskSecuritySHA256){throw 'Target native security capture differs from the imported target inventory.'}
    $snapshotUtc=[DateTimeOffset]::MinValue;if(-not $targetInventory.PSObject.Properties['CreatedUtc'] -or -not [DateTimeOffset]::TryParse([string]$targetInventory.CreatedUtc,[ref]$snapshotUtc) -or $snapshotUtc.Offset -ne [TimeSpan]::Zero -or ([DateTimeOffset]::UtcNow-$snapshotUtc).TotalHours -gt 24 -or ([DateTimeOffset]::UtcNow-$snapshotUtc).TotalMinutes -lt -5){throw 'Target inventory snapshot is stale, future-dated, or has no UTC capture timestamp.'}
    $baseline=Read-WsmTrustedJson $BaselinePath $BaselineHash
    $baselineFields=@('SchemaVersion','ToolVersion','Kind','BaselineId','ProviderId','Source','Target','SourceCapturePath','SourceCaptureHash','TargetCapturePath','TargetCaptureHash','BaselineOwner','PristineAcknowledged','VendorVerified','ReadinessProof','BusinessAcceptance','ExternalProvenanceRetention','CreatedUtc')
    Assert-WsmFields $baseline $baselineFields $baselineFields
    if($baseline.SchemaVersion -ne 1 -or $baseline.Kind -cne 'TrustedOsProvidedTaskBaseline' -or -not $baseline.BaselineId -or -not $baseline.ProviderId -or -not $baseline.PristineAcknowledged -or $baseline.VendorVerified -or $baseline.ReadinessProof -or $baseline.BusinessAcceptance){throw 'Trusted baseline evidence is malformed, unacknowledged, or claims authority it cannot establish.'}
    foreach($side in @('Source','Target')){Assert-WsmFields $baseline.$side @('OS','Version','Build','Edition','Architecture','TaskPath','TaskName','TaskXmlSHA256','TaskSecuritySHA256','ProvenanceReference','ProvenanceSHA256','ProvenanceOwner') @('OS','Version','Build','Edition','Architecture','TaskPath','TaskName','TaskXmlSHA256','TaskSecuritySHA256','ProvenanceReference','ProvenanceSHA256','ProvenanceOwner');if([string]$baseline.$side.ProvenanceSHA256 -notmatch '^[a-fA-F0-9]{64}$' -or -not $baseline.$side.ProvenanceReference -or -not $baseline.$side.ProvenanceOwner){throw ($side+' OS provider provenance reference is incomplete.')}}
    $sourceBaselineMatch=([string]$baseline.Source.OS -ceq $sourceDef.HostOS -and [string]$baseline.Source.Version -ceq $sourceDef.HostVersion -and [string]$baseline.Source.Build -ceq $sourceDef.HostBuild -and [string]$baseline.Source.Edition -ceq $sourceDef.HostEdition -and [string]$baseline.Source.Architecture -ceq $sourceDef.HostArchitecture -and [string]$baseline.Source.TaskPath -ceq $sourceDef.TaskPath -and [string]$baseline.Source.TaskName -ceq $sourceDef.TaskName -and [string]$baseline.Source.TaskXmlSHA256 -ieq $sourceDef.TaskXmlSHA256 -and [string]$baseline.Source.TaskSecuritySHA256 -ieq $sourceDef.TaskSecuritySHA256)
    $targetBaselineMatch=([string]$baseline.Target.OS -ceq $targetDef.HostOS -and [string]$baseline.Target.Version -ceq $targetDef.HostVersion -and [string]$baseline.Target.Build -ceq $targetDef.HostBuild -and [string]$baseline.Target.Edition -ceq $targetDef.HostEdition -and [string]$baseline.Target.Architecture -ceq $targetDef.HostArchitecture -and [string]$baseline.Target.TaskPath -ceq $targetDef.TaskPath -and [string]$baseline.Target.TaskName -ceq $targetDef.TaskName -and [string]$baseline.Target.TaskXmlSHA256 -ieq $targetDef.TaskXmlSHA256 -and [string]$baseline.Target.TaskSecuritySHA256 -ieq $targetDef.TaskSecuritySHA256)
    $definitionDiffers=($sourceDef.TaskXmlSHA256 -ine $targetDef.TaskXmlSHA256 -or $sourceDef.TaskSecuritySHA256 -ine $targetDef.TaskSecuritySHA256)
    $manualReasons=New-Object 'System.Collections.Generic.List[string]';if(-not $sourceBaselineMatch){$manualReasons.Add('SourceDefinitionDoesNotMatchTrustedBaseline')};if(-not $targetBaselineMatch){$manualReasons.Add('TargetDefinitionDoesNotMatchTrustedBaseline')};if($targetItems[0].Status -in @('Unsupported','Failed','PermissionDenied')){$manualReasons.Add('TargetTaskStatusNotVerified')}
    $isProven=($sourceBaselineMatch -and $targetBaselineMatch -and $manualReasons.Count -eq 0)
    [pscustomobject][ordered]@{Kind='AssistiveOsProvidedReview';Status='Previewed';PairId=[string]$catalog.PairId;ItemId=[string]$ItemId;SourceInventoryHash=[string]$catalog.InventoryHash;DecisionRevision=[int]$catalog.DecisionRevision;TargetFingerprint=[string]$targetInventory.Source.Fingerprint;TargetSnapshotHash=[string]$TargetInventoryHash.ToLowerInvariant();TargetSnapshotUtc=$targetInventory.CreatedUtc;SourceTaskXmlSHA256=$sourceDef.TaskXmlSHA256;SourceTaskSecuritySHA256=$sourceDef.TaskSecuritySHA256;TargetTaskXmlSHA256=$targetDef.TaskXmlSHA256;TargetTaskSecuritySHA256=$targetDef.TaskSecuritySHA256;SourceProviderProvenanceReference=[string]$baseline.Source.ProvenanceReference;TargetProviderProvenanceReference=[string]$baseline.Target.ProvenanceReference;ProviderId=[string]$baseline.ProviderId;TrustedBaselinePath=[IO.Path]::GetFullPath($BaselinePath);TrustedBaselineHash=$BaselineHash.ToLowerInvariant();TrustedBaselineOwner=$BaselineOwner;SourceBaselineMatched=$sourceBaselineMatch;TargetBaselineMatched=$targetBaselineMatch;DefinitionsDiffer=$definitionDiffers;OSProvidedEligible=$isProven;ManualReasons=@($manualReasons.ToArray());ValuesWithheld=$true;VendorVerified=$false;ReadinessProof=$false;BusinessAcceptance=$false;RawDefinitionsIncluded=$false}
}

function Submit-WsmAssistiveOsProvidedReview {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$Workspace,[Parameter(Mandatory)][string]$PairId,[Parameter(Mandatory)][string]$ItemId,[Parameter(Mandatory)][int]$ExpectedDecisionRevision,[Parameter(Mandatory)][string]$SourceCapturePath,[Parameter(Mandatory)][string]$SourceCaptureHash,[Parameter(Mandatory)][string]$TargetCapturePath,[Parameter(Mandatory)][string]$TargetCaptureHash,[Parameter(Mandatory)][string]$TargetInventoryPath,[Parameter(Mandatory)][string]$TargetInventoryHash,[Parameter(Mandatory)][string]$BaselinePath,[Parameter(Mandatory)][string]$BaselineHash,[Parameter(Mandatory)][string]$BaselineOwner,[Parameter(Mandatory)][string]$Owner,[Parameter(Mandatory)][ValidateSet('OSProvided','Manual')][string]$Disposition,[Parameter(Mandatory)][string]$Reason,[Parameter(Mandatory)][switch]$Ack,[Parameter(Mandatory)][switch]$AckTrustedBaseline,[switch]$AckDefinitionDifference)
    if(-not $Ack){throw 'Submitting OSProvided review requires explicit owner acknowledgment.'}
    Assert-WsmQualificationText $Owner Owner;Assert-WsmQualificationText $Reason Reason 2048
    $review=Get-WsmAssistiveOsProvidedReview -Workspace $Workspace -PairId $PairId -ItemId $ItemId -SourceCapturePath $SourceCapturePath -SourceCaptureHash $SourceCaptureHash -TargetCapturePath $TargetCapturePath -TargetCaptureHash $TargetCaptureHash -TargetInventoryPath $TargetInventoryPath -TargetInventoryHash $TargetInventoryHash -BaselinePath $BaselinePath -BaselineHash $BaselineHash -BaselineOwner $BaselineOwner -AckTrustedBaseline:$AckTrustedBaseline
    if($Disposition -ceq 'OSProvided' -and -not $review.OSProvidedEligible){throw 'OSProvided was rejected: source and target definitions must each exactly match their independently trusted OS baseline; keep this item manual.'}
    if($review.DefinitionsDiffer -and -not $AckDefinitionDifference){throw 'Source and target OS definitions differ; explicit acknowledgment and reason are required.'}
    $catalog=Get-WsmCatalog $Workspace $PairId;if($catalog.DecisionRevision -ne $ExpectedDecisionRevision -or $review.DecisionRevision -ne $ExpectedDecisionRevision){throw 'Catalog changed; refresh the OSProvided review before submitting.'}
    $identity=Get-WsmMachineIdentity
    if($identity.Fingerprint -ine $review.TargetFingerprint){throw 'OSProvided submit must run on the exact reviewed target host for current native readback.'}
    $sourceCapture=Read-WsmAssistiveOsProvidedCapture $SourceCapturePath $SourceCaptureHash
    $currentXml=[string](Export-ScheduledTask -TaskName ([string]$sourceCapture.TaskName) -TaskPath ([string]$sourceCapture.TaskPath) -ErrorAction Stop)
    $currentSecurity=Capture-WsmTaskSecurity ([string]$sourceCapture.TaskPath) ([string]$sourceCapture.TaskName)
    $currentSecurityHash=Get-WsmHashText ((Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $currentSecurity) | ConvertTo-Json -Depth 30 -Compress)
    if((Get-WsmHashText $currentXml) -ine $review.TargetTaskXmlSHA256 -or $currentSecurityHash -ine $review.TargetTaskSecuritySHA256){throw 'Current native target task readback changed since preview; refresh the target capture.'}
    $proofStatus='ManualRequired';if($Disposition -ceq 'OSProvided'){$proofStatus='OwnerAcceptedOsProvidedBaselineMatch'}
    $receipt=[pscustomobject][ordered]@{SchemaVersion=1;Kind='AssistiveOsProvidedReviewEvidence';PairId=$PairId;ItemId=$ItemId;SourceInventoryHash=$review.SourceInventoryHash;SourceItemSettingsHash=[string]$catalog.Items.Where({$_.ItemId -ceq $ItemId})[0].SettingsHash;ReviewDecisionRevision=[int]$ExpectedDecisionRevision;DecisionRevision=([int]$ExpectedDecisionRevision+1);TargetFingerprint=$review.TargetFingerprint;TargetSnapshotHash=$review.TargetSnapshotHash;TargetSnapshotUtc=$review.TargetSnapshotUtc;NativeTargetReadbackUtc=(Get-WsmUtc);SourceCaptureHash=$SourceCaptureHash.ToLowerInvariant();TargetCaptureHash=$TargetCaptureHash.ToLowerInvariant();TaskPath=[string]$sourceCapture.TaskPath;TaskName=[string]$sourceCapture.TaskName;SourceTaskXmlSHA256=$review.SourceTaskXmlSHA256;SourceTaskSecuritySHA256=$review.SourceTaskSecuritySHA256;TargetTaskXmlSHA256=$review.TargetTaskXmlSHA256;TargetTaskSecuritySHA256=$review.TargetTaskSecuritySHA256;ProviderId=$review.ProviderId;SourceProviderProvenanceReference=$review.SourceProviderProvenanceReference;TargetProviderProvenanceReference=$review.TargetProviderProvenanceReference;TrustedBaselinePath=$review.TrustedBaselinePath;TrustedBaselineHash=$review.TrustedBaselineHash;TrustedBaselineOwner=$review.TrustedBaselineOwner;ExternalProvenanceRetention='External provenance files remain owner-managed and are not automatically cleaned by this workspace.';SourceBaselineMatched=[bool]$review.SourceBaselineMatched;TargetBaselineMatched=[bool]$review.TargetBaselineMatched;DefinitionsDiffer=[bool]$review.DefinitionsDiffer;Disposition=$Disposition;Status=$proofStatus;Owner=$Owner;Reason=$Reason;TrustedBaselineAcknowledged=$true;DefinitionDifferenceAcknowledged=[bool]$AckDefinitionDifference;VendorVerified=$false;ReadinessProof=$false;BusinessAcceptance=$false;CreatedUtc=(Get-WsmUtc)}
    $out=Get-WsmAssistiveFormDecisionPath $Workspace $PairId $ExpectedDecisionRevision 'osprovided-review';Write-WsmJson $out $receipt;$receiptHash=(Get-FileHash -LiteralPath $out -Algorithm SHA256).Hash.ToLowerInvariant()
    try {
        $materials=@([pscustomobject]@{Path=$out;SHA256=$receiptHash;Kind='OsProvidedReviewReceipt'},[pscustomobject]@{Path=$BaselinePath;SHA256=$BaselineHash;Kind='OsProvidedTrustedBaseline'},[pscustomobject]@{Path=$SourceCapturePath;SHA256=$SourceCaptureHash;Kind='OsProvidedSourceTaskCapture'},[pscustomobject]@{Path=$TargetCapturePath;SHA256=$TargetCaptureHash;Kind='OsProvidedTargetTaskCapture'})
        if(-not (Get-Command Register-WsmAssistiveMaterialBatch -ErrorAction SilentlyContinue)){throw 'Assistive material retention support is required to submit OSProvided evidence.'}
        Register-WsmAssistiveMaterialBatch $Workspace $PairId 0 $materials @('OSProvidedReview|'+$PairId+'|'+$ItemId) | Out-Null
        Invoke-WsmLocked $Workspace {
            $current=Get-WsmCatalog $Workspace $PairId
            if($current.DecisionRevision -ne $ExpectedDecisionRevision -or $current.InventoryHash -ine $receipt.SourceInventoryHash){throw 'Catalog changed during OSProvided submit; no disposition was applied.'}
            $items=@($current.Items | Where-Object ItemId -CEQ $ItemId);if($items.Count -ne 1 -or $items[0].Adapter -cne 'ScheduledTask'){throw 'Selected source task no longer exists in the current catalog.'}
            if(-not $current.PSObject.Properties['GeneralHost']){throw 'Enable GeneralHost mode before applying an OSProvided object disposition.'}
            $item=$items[0];$item.Decision='Exclude';$item.Reason=$Reason;$item.Owner=$Owner;$item.Evidence=('Typed OSProvided review '+$receiptHash);$item | Add-Member NoteProperty ReviewedBy ([string](Get-WsmExecutionActor).WindowsPrincipal) -Force;$item | Add-Member NoteProperty ReviewedUtc (Get-WsmUtc) -Force
            $override=[pscustomobject][ordered]@{Disposition='External';Owner=$Owner;Reason=$Reason;Evidence=('Typed OSProvided review '+$receiptHash);SourceHash=$current.InventoryHash;Utc=(Get-WsmUtc);OsProvidedReview=[pscustomobject][ordered]@{EvidencePath=[IO.Path]::GetFullPath($out);EvidenceHash=$receiptHash;ItemId=$ItemId;DecisionRevision=($ExpectedDecisionRevision+1);TargetFingerprint=$review.TargetFingerprint;TargetSnapshotHash=$review.TargetSnapshotHash;Disposition=$Disposition;Status=$proofStatus}}
            $item | Add-Member NoteProperty GeneralHostOverride $override -Force
            $current.DecisionRevision++;$current.Approval=$null;$current.GeneralHost.UpdatedUtc=Get-WsmUtc;$current.History=@($current.History)+@([pscustomobject]@{Actor=(Get-WsmExecutionActor);Revision=$current.DecisionRevision;Action='AssistiveOsProvidedReview';ItemId=$ItemId;SourceHash=$current.InventoryHash;EvidenceHash=$receiptHash;Disposition=$Disposition;Utc=(Get-WsmUtc)})
            if($current.PSObject.Properties['Assistive']){Clear-WsmAssistiveComparison $current}
            Assert-WsmGeneralHostContract $current | Out-Null;Write-WsmJson (Get-WsmCatalogPath $Workspace $PairId) $current
            $current
        } | Out-Null
    } catch { throw }
    [pscustomobject][ordered]@{Status=$proofStatus;PairId=$PairId;ItemId=$ItemId;DecisionRevision=($ExpectedDecisionRevision+1);EvidencePath=[IO.Path]::GetFullPath($out);EvidenceHash=$receiptHash;Disposition=$Disposition;ValuesWithheld=$true;VendorVerified=$false;ReadinessProof=$false;BusinessAcceptance=$false}
}

function New-WsmAssistiveOsProvidedSealedEvidence {
    [CmdletBinding()]param([Parameter(Mandatory)]$Catalog,[Parameter(Mandatory)]$Item)
    Assert-WsmAssistiveContract $Catalog Catalog | Out-Null
    $catalogItems=@($Catalog.Items | Where-Object {[string]$_.ItemId -ceq [string]$Item.ItemId});if($catalogItems.Count -ne 1){throw ('Sealed OSProvided snapshot requires one exact current catalog item; matches='+$catalogItems.Count)};$catalogItem=$catalogItems[0];if([string]$catalogItem.SettingsHash -ine [string]$Item.SettingsHash -or [string]$catalogItem.Decision -cne 'Exclude' -or -not $catalogItem.PSObject.Properties['GeneralHostOverride'] -or -not $catalogItem.GeneralHostOverride.PSObject.Properties['OsProvidedReview']){throw ('Sealed OSProvided snapshot requires the exact current excluded catalog item; catalogDecision='+[string]$catalogItem.Decision+'; itemDecision='+[string]$Item.Decision+'; catalogSettings='+[string]$catalogItem.SettingsHash+'; itemSettings='+[string]$Item.SettingsHash+'; hasReview='+[bool]($catalogItem.PSObject.Properties['GeneralHostOverride'] -and $catalogItem.GeneralHostOverride.PSObject.Properties['OsProvidedReview']))}
    $validationIssues=@(Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $Catalog -ItemId ([string]$Item.ItemId));if($validationIssues.Count){throw ('Current OSProvided evidence is invalid and cannot be sealed: '+[string]$validationIssues[0].Issue)}
    $ref=$catalogItems[0].GeneralHostOverride.OsProvidedReview;$receipt=Read-WsmTrustedJson ([string]$ref.EvidencePath) ([string]$ref.EvidenceHash)
    $baseline=Read-WsmTrustedJson ([string]$receipt.TrustedBaselinePath) ([string]$receipt.TrustedBaselineHash)
    Assert-WsmTrustedFile ([string]$baseline.Source.ProvenanceReference) ([string]$baseline.Source.ProvenanceSHA256);Assert-WsmTrustedFile ([string]$baseline.Target.ProvenanceReference) ([string]$baseline.Target.ProvenanceSHA256)
    $safeReceipt=ConvertFrom-WsmJson (ConvertTo-Json -InputObject $receipt -Depth 60 -Compress)
    $safeReceipt.TrustedBaselinePath='Verified at source sealing; original host path withheld.';$safeReceipt.SourceProviderProvenanceReference='Verified at source sealing; original host path withheld.';$safeReceipt.TargetProviderProvenanceReference='Verified at source sealing; original host path withheld.'
    $safeBaseline=ConvertFrom-WsmJson (ConvertTo-Json -InputObject $baseline -Depth 40 -Compress)
    $safeBaseline.Source.ProvenanceReference='Verified at source sealing; original host path withheld.';$safeBaseline.Target.ProvenanceReference='Verified at source sealing; original host path withheld.'
    $snapshot=[pscustomobject][ordered]@{SchemaVersion=1;Kind='AssistiveOsProvidedSealedEvidence';PairId=[string]$Catalog.PairId;ItemId=[string]$Item.ItemId;SourceInventoryHash=[string]$Catalog.InventoryHash;SourceItemSettingsHash=[string]$catalogItems[0].SettingsHash;VerifiedAtSealUtc=(Get-WsmUtc);SourceAtSeal=[pscustomobject][ordered]@{EvidenceVerified=$true;ProvenanceVerified=$true;ReceiptPhysicalSHA256=[string]$ref.EvidenceHash;BaselinePhysicalSHA256=[string]$receipt.TrustedBaselineHash;SourceProvenanceSHA256=[string]$baseline.Source.ProvenanceSHA256;TargetProvenanceSHA256=[string]$baseline.Target.ProvenanceSHA256;SourceProvenanceOwner=[string]$baseline.Source.ProvenanceOwner;TargetProvenanceOwner=[string]$baseline.Target.ProvenanceOwner;Custody='Source producer verified original receipt, baseline, and provenance bytes before sealing; target does not reverify external provenance.'};Receipt=$safeReceipt;Baseline=$safeBaseline;VendorVerified=$false;ReadinessProof=$false;BusinessAcceptance=$false;RawTaskDefinitionsIncluded=$false}
    $snapshot | Add-Member NoteProperty SnapshotHash (Get-WsmHashText ($snapshot | ConvertTo-Json -Depth 70 -Compress))
    $snapshot
}

function Get-WsmAssistiveOsProvidedIssues {
    [CmdletBinding()]param([Parameter(Mandatory)]$CatalogOrPlan,[string]$ItemId='',[string]$TargetFingerprint='',[string]$TargetSnapshotHash='',[switch]$VerifyNativeTarget)
    $topLevelKind='';if($CatalogOrPlan.PSObject.Properties['Kind']){$topLevelKind=[string]$CatalogOrPlan.Kind};$sealedPlan=($topLevelKind -ceq 'MigrationPlan' -or ($CatalogOrPlan.PSObject.Properties['Approval'] -and $CatalogOrPlan.Approval -and $CatalogOrPlan.Approval.PSObject.Properties['Kind'] -and [string]$CatalogOrPlan.Approval.Kind -ceq 'MigrationPlan'))
    $allItems=New-Object 'System.Collections.Generic.List[object]';foreach($candidate in @($CatalogOrPlan.Items)){$allItems.Add($candidate)}
    if($CatalogOrPlan.PSObject.Properties['Assistive'] -and $CatalogOrPlan.Assistive -and $CatalogOrPlan.Assistive.PSObject.Properties['DiscoveryAuthority'] -and $CatalogOrPlan.Assistive.DiscoveryAuthority -and $CatalogOrPlan.Assistive.DiscoveryAuthority.PSObject.Properties['OsProvidedItems']){foreach($candidate in @($CatalogOrPlan.Assistive.DiscoveryAuthority.OsProvidedItems)){$existing=@($allItems | Where-Object ItemId -CEQ ([string]$candidate.ItemId));if(-not $existing.Count){$allItems.Add($candidate)}elseif(($existing[0]|ConvertTo-Json -Depth 40 -Compress) -cne ($candidate|ConvertTo-Json -Depth 40 -Compress)){$allItems.Add($candidate)}}}
    $items=@($allItems.ToArray());if($ItemId){$items=@($items | Where-Object ItemId -CEQ $ItemId)}elseif($CatalogOrPlan.PSObject.Properties['Assistive'] -and $CatalogOrPlan.Assistive){$selectionRows=$null;if($sealedPlan -and $CatalogOrPlan.Assistive.PSObject.Properties['DiscoveryAuthority'] -and $CatalogOrPlan.Assistive.DiscoveryAuthority -and $CatalogOrPlan.Assistive.DiscoveryAuthority.PSObject.Properties['Dispositions']){$selectionRows=$CatalogOrPlan.Assistive.DiscoveryAuthority.Dispositions}elseif($CatalogOrPlan.Assistive.PSObject.Properties['TargetSelections'] -and $CatalogOrPlan.Assistive.TargetSelections){$selectionRows=$CatalogOrPlan.Assistive.TargetSelections.Items}elseif($CatalogOrPlan.Assistive.PSObject.Properties['Selections'] -and $CatalogOrPlan.Assistive.Selections){$selectionRows=$CatalogOrPlan.Assistive.Selections.Items};if($null -ne $selectionRows){$selected=@{};foreach($row in @($selectionRows)){if($row.Selected){$selected[[string]$row.ItemId]=$true}};$items=@($items | Where-Object {$selected.ContainsKey([string]$_.ItemId)})}};$issues=New-Object 'System.Collections.Generic.List[object]'
    foreach($item in $items){
        if(-not $item.PSObject.Properties['GeneralHostOverride'] -or -not $item.GeneralHostOverride.PSObject.Properties['OsProvidedReview']){continue}
        $ref=$item.GeneralHostOverride.OsProvidedReview;$issue=''
        try {
            Assert-WsmFields $ref @('EvidencePath','EvidenceHash','ItemId','DecisionRevision','TargetFingerprint','TargetSnapshotHash','Disposition','Status') @('EvidencePath','EvidenceHash','ItemId','DecisionRevision','TargetFingerprint','TargetSnapshotHash','Disposition','Status')
            $sealedSnapshot=$null
            if($sealedPlan){
                Assert-WsmAssistiveContract $CatalogOrPlan MigrationPlan | Out-Null
                if(-not $item.PSObject.Properties['GeneralHostOverride'] -or -not $item.GeneralHostOverride.PSObject.Properties['OsProvidedSealedEvidence']){throw 'Sealed plan is missing its source-verified portable OSProvided evidence snapshot.'}
                $sealedSnapshot=$item.GeneralHostOverride.OsProvidedSealedEvidence
                Assert-WsmFields $sealedSnapshot @('SchemaVersion','Kind','PairId','ItemId','SourceInventoryHash','SourceItemSettingsHash','VerifiedAtSealUtc','SourceAtSeal','Receipt','Baseline','VendorVerified','ReadinessProof','BusinessAcceptance','RawTaskDefinitionsIncluded','SnapshotHash') @('SchemaVersion','Kind','PairId','ItemId','SourceInventoryHash','SourceItemSettingsHash','VerifiedAtSealUtc','SourceAtSeal','Receipt','Baseline','SnapshotHash')
                $snapshotHash=[string]$sealedSnapshot.SnapshotHash;$snapshotCopy=ConvertFrom-WsmJson (ConvertTo-Json -InputObject $sealedSnapshot -Depth 80 -Compress);$snapshotCopy.PSObject.Properties.Remove('SnapshotHash')
                if($sealedSnapshot.SchemaVersion -ne 1 -or [string]$sealedSnapshot.Kind -cne 'AssistiveOsProvidedSealedEvidence' -or [string]$sealedSnapshot.PairId -cne [string]$CatalogOrPlan.PairId -or [string]$sealedSnapshot.ItemId -cne [string]$item.ItemId -or [string]$sealedSnapshot.SourceInventoryHash -ine [string]$CatalogOrPlan.InventoryHash -or [string]$sealedSnapshot.SourceItemSettingsHash -ine [string]$item.SettingsHash -or [string]$sealedSnapshot.SourceAtSeal.ReceiptPhysicalSHA256 -ine [string]$ref.EvidenceHash -or $snapshotHash -notmatch '^[a-f0-9]{64}$' -or (Get-WsmHashText ($snapshotCopy|ConvertTo-Json -Depth 80 -Compress)) -ine $snapshotHash -or -not $sealedSnapshot.SourceAtSeal.EvidenceVerified -or -not $sealedSnapshot.SourceAtSeal.ProvenanceVerified -or $sealedSnapshot.VendorVerified -or $sealedSnapshot.ReadinessProof -or $sealedSnapshot.BusinessAcceptance -or $sealedSnapshot.RawTaskDefinitionsIncluded){throw 'Portable sealed OSProvided snapshot integrity, source binding, or trust boundary is invalid.'}
                foreach($hashName in @('ReceiptPhysicalSHA256','BaselinePhysicalSHA256','SourceProvenanceSHA256','TargetProvenanceSHA256')){if([string]$sealedSnapshot.SourceAtSeal.$hashName -notmatch '^[a-f0-9]{64}$'){throw ('Sealed source-at-seal physical hash is malformed: '+$hashName)}}
                $sealTime=[DateTimeOffset]::MinValue;if(-not [DateTimeOffset]::TryParse([string]$sealedSnapshot.VerifiedAtSealUtc,[ref]$sealTime) -or $sealTime.Offset -ne [TimeSpan]::Zero -or $sealTime -gt [DateTimeOffset]::UtcNow.AddMinutes(5)){throw 'Sealed OSProvided evidence source-verification timestamp is invalid or future-dated.'}
                $evidence=$sealedSnapshot.Receipt;$baseline=$sealedSnapshot.Baseline
            }else{$evidence=Read-WsmTrustedJson ([string]$ref.EvidencePath) ([string]$ref.EvidenceHash)}
            $evidenceFields=@('SchemaVersion','Kind','PairId','ItemId','SourceInventoryHash','SourceItemSettingsHash','ReviewDecisionRevision','DecisionRevision','TargetFingerprint','TargetSnapshotHash','TargetSnapshotUtc','NativeTargetReadbackUtc','SourceCaptureHash','TargetCaptureHash','TaskPath','TaskName','SourceTaskXmlSHA256','SourceTaskSecuritySHA256','TargetTaskXmlSHA256','TargetTaskSecuritySHA256','ProviderId','SourceProviderProvenanceReference','TargetProviderProvenanceReference','TrustedBaselinePath','TrustedBaselineHash','TrustedBaselineOwner','ExternalProvenanceRetention','SourceBaselineMatched','TargetBaselineMatched','DefinitionsDiffer','Disposition','Status','Owner','Reason','TrustedBaselineAcknowledged','DefinitionDifferenceAcknowledged','VendorVerified','ReadinessProof','BusinessAcceptance','CreatedUtc')
            Assert-WsmFields $evidence $evidenceFields $evidenceFields
            foreach($timestampName in @('TargetSnapshotUtc','NativeTargetReadbackUtc','CreatedUtc')){$parsedTimestamp=[DateTimeOffset]::MinValue;if(-not [DateTimeOffset]::TryParse([string]$evidence.$timestampName,[ref]$parsedTimestamp) -or $parsedTimestamp.Offset -ne [TimeSpan]::Zero -or $parsedTimestamp -gt [DateTimeOffset]::UtcNow.AddMinutes(5)){throw ('OSProvided receipt timestamp is invalid or future-dated: '+$timestampName)}}
            if($evidence.SchemaVersion -ne 1 -or $evidence.Kind -cne 'AssistiveOsProvidedReviewEvidence' -or [string]$evidence.PairId -cne [string]$CatalogOrPlan.PairId -or [string]$evidence.ItemId -cne [string]$item.ItemId -or [string]$evidence.SourceInventoryHash -ine [string]$CatalogOrPlan.InventoryHash -or [string]$evidence.SourceItemSettingsHash -ine [string]$item.SettingsHash -or [int]$evidence.DecisionRevision -gt [int]$CatalogOrPlan.DecisionRevision -or [int]$ref.DecisionRevision -ne [int]$evidence.DecisionRevision -or [string]$evidence.TargetFingerprint -ine [string]$ref.TargetFingerprint -or [string]$evidence.TargetSnapshotHash -ine [string]$ref.TargetSnapshotHash -or [string]$evidence.Disposition -cne [string]$ref.Disposition -or -not $evidence.TrustedBaselineAcknowledged -or $evidence.VendorVerified -or $evidence.ReadinessProof -or $evidence.BusinessAcceptance){throw 'OSProvided evidence binding or trust claim is invalid.'}
            if($TargetFingerprint -and [string]$evidence.TargetFingerprint -ine $TargetFingerprint){throw 'Current target fingerprint differs from reviewed evidence.'}
            if($TargetSnapshotHash -and [string]$evidence.TargetSnapshotHash -ine $TargetSnapshotHash){throw 'Current target snapshot differs from reviewed evidence.'}
            $readback=[DateTimeOffset]::Parse([string]$evidence.NativeTargetReadbackUtc)
            if(-not $sealedPlan -and ([DateTimeOffset]::UtcNow-$readback).TotalHours -gt 24){throw 'Native target readback is stale, future-dated, or has no UTC timestamp.'}
            if(-not $sealedPlan){$baseline=Read-WsmTrustedJson ([string]$evidence.TrustedBaselinePath) ([string]$evidence.TrustedBaselineHash)}
            if($baseline.Kind -cne 'TrustedOsProvidedTaskBaseline' -or -not $baseline.PristineAcknowledged -or $baseline.VendorVerified){throw 'Trusted OS/provider baseline trust declaration is invalid.'}
            if([string]$baseline.ExternalProvenanceRetention -cne 'External provenance files remain owner-managed and are not automatically cleaned by this workspace.' -or [string]$evidence.ExternalProvenanceRetention -cne [string]$baseline.ExternalProvenanceRetention){throw 'External provenance retention declaration is missing.'}
            if($sealedPlan){if([string]$sealedSnapshot.SourceAtSeal.SourceProvenanceSHA256 -ine [string]$baseline.Source.ProvenanceSHA256 -or [string]$sealedSnapshot.SourceAtSeal.TargetProvenanceSHA256 -ine [string]$baseline.Target.ProvenanceSHA256 -or [string]$sealedSnapshot.SourceAtSeal.BaselinePhysicalSHA256 -ine [string]$evidence.TrustedBaselineHash){throw 'Sealed source-at-seal provenance or physical baseline hash binding is invalid.'}}
            else{Assert-WsmTrustedFile ([string]$baseline.Source.ProvenanceReference) ([string]$baseline.Source.ProvenanceSHA256);Assert-WsmTrustedFile ([string]$baseline.Target.ProvenanceReference) ([string]$baseline.Target.ProvenanceSHA256)}
            $sourceMatches=([string]$baseline.Source.TaskXmlSHA256 -ieq [string]$evidence.SourceTaskXmlSHA256 -and [string]$baseline.Source.TaskSecuritySHA256 -ieq [string]$evidence.SourceTaskSecuritySHA256)
            $targetMatches=([string]$baseline.Target.TaskXmlSHA256 -ieq [string]$evidence.TargetTaskXmlSHA256 -and [string]$baseline.Target.TaskSecuritySHA256 -ieq [string]$evidence.TargetTaskSecuritySHA256)
            $definitionsDiffer=([string]$evidence.SourceTaskXmlSHA256 -ine [string]$evidence.TargetTaskXmlSHA256 -or [string]$evidence.SourceTaskSecuritySHA256 -ine [string]$evidence.TargetTaskSecuritySHA256)
            if([bool]$evidence.SourceBaselineMatched -ne $sourceMatches -or [bool]$evidence.TargetBaselineMatched -ne $targetMatches -or [bool]$evidence.DefinitionsDiffer -ne $definitionsDiffer){throw 'Evidence baseline-match or definition-difference claims do not match their bound hashes.'}
            if([string]$evidence.Disposition -ceq 'OSProvided' -and ([string]$evidence.Status -cne 'OwnerAcceptedOsProvidedBaselineMatch' -or -not $sourceMatches -or -not $targetMatches)){throw 'OSProvided evidence does not prove exact source and target baseline matches.'}
            if([string]$evidence.Disposition -ceq 'Manual'){
                if([string]$evidence.Status -cne 'ManualRequired' -or [string]$ref.Status -cne 'ManualRequired'){throw 'Manual evidence must remain in the ManualRequired state.'}
                if([string]::IsNullOrWhiteSpace([string]$evidence.Owner) -or [string]::IsNullOrWhiteSpace([string]$evidence.Reason)){throw 'Manual handling lacks an owner-reviewed reason.'}
                if([string]$item.GeneralHostOverride.Owner -cne [string]$evidence.Owner -or [string]$item.GeneralHostOverride.Reason -cne [string]$evidence.Reason){throw 'Manual evidence owner/reason differs from the current owner-reviewed disposition.'}
            }
            if([string]$evidence.Disposition -notin @('OSProvided','Manual')){throw 'Unknown OSProvided disposition.'}
            if($VerifyNativeTarget){
                if([string]$evidence.Disposition -cne 'OSProvided'){continue}
                $identity=Get-WsmMachineIdentity
                $requiredFingerprint=[string]$ref.TargetFingerprint;if($TargetFingerprint){$requiredFingerprint=$TargetFingerprint}
                if([string]::IsNullOrWhiteSpace($requiredFingerprint) -or [string]$identity.Fingerprint -ine $requiredFingerprint -or [string]$evidence.TargetFingerprint -ine $requiredFingerprint){throw 'Native target machine fingerprint differs from the reviewed target.'}
                $nativeTask=Get-ScheduledTask -TaskPath ([string]$evidence.TaskPath) -TaskName ([string]$evidence.TaskName) -ErrorAction Stop
                if($null -eq $nativeTask){throw 'Reviewed target task is no longer present on the native target.'}
                $nativeXml=Export-ScheduledTask -TaskPath ([string]$evidence.TaskPath) -TaskName ([string]$evidence.TaskName) -ErrorAction Stop
                $nativeSecurity=Capture-WsmTaskSecurity ([string]$evidence.TaskPath) ([string]$evidence.TaskName)
                $nativeXmlHash=Get-WsmHashText ([string]$nativeXml)
                $nativeSecurityHash=Get-WsmHashText ((Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $nativeSecurity) | ConvertTo-Json -Depth 30 -Compress)
                if($nativeXmlHash -ine [string]$evidence.TargetTaskXmlSHA256 -or $nativeSecurityHash -ine [string]$evidence.TargetTaskSecuritySHA256){throw 'Native target task XML or security differs from the reviewed OSProvided evidence.'}
            }
        } catch { $issue=('OSProvided evidence rejected: '+[string]$_.Exception.Message) }
        if($issue){$issues.Add([pscustomobject][ordered]@{ItemId=[string]$item.ItemId;Issue=$issue;ManualReviewRequired=$true;ReadinessProof=$false})}
    }
    @($issues.ToArray())
}
